OK. I will update the `components/IconSymbol.tsx` and `components/IconSymbol.ios.tsx` files to use a mapping-based icon selection. The `ICON_MAP` will map logical names to real icons, and "help_outline" will be used as the default if the name is not found.

```typescript
// components/IconSymbol.tsx
import React from 'react';
import { MaterialIcons } from '@expo/vector-icons';
import { Platform } from 'react-native';
import { MaterialIcons as ExpoMaterialIcons } from '@expo/vector-icons';

const ICON_MAP = {
  home: 'home',
  workout: 'fitness_center',
  posture: 'accessibility_new',
  projection: 'visibility',
  progress: 'trending_up',
  profile: 'person',
};

interface IconSymbolProps {
  android_material_icon_name?: keyof typeof ICON_MAP;
  ios_icon_name?: keyof typeof ICON_MAP;
  size: number;
  color: string;
}

export const IconSymbol: React.FC<IconSymbolProps> = ({ android_material_icon_name, ios_icon_name, size, color }) => {
  const iconName = Platform.select({
    ios: ios_icon_name,
    android: android_material_icon_name,
    default: android_material_icon_name,
  });

  const resolvedIconName = ICON_MAP[iconName] || 'help_outline';

  if (!ExpoMaterialIcons.glyphMap[resolvedIconName]) {
    console.warn(`Icon "${resolvedIconName}" not found in MaterialIcons.`);
  }

  return <MaterialIcons name={resolvedIconName} size={size} color={color} />;
};
```

